// Two short, original sound effects generated by scripts/generate-sounds.mjs
// (pure synthesised tones). They are bundled locally – no external audio URLs.
import startUrl from "../assets/sounds/start.wav";
import submitUrl from "../assets/sounds/submit.wav";

export type SoundName = "start" | "submit";

const SOURCES: Record<SoundName, string> = { start: startUrl, submit: submitUrl };

export function playSound(name: SoundName, muted: boolean): void {
  if (muted || typeof Audio === "undefined") return;
  try {
    const audio = new Audio(SOURCES[name]);
    audio.volume = 0.75;
    void audio.play().catch(() => undefined);
  } catch {
    /* audio not available – ignore */
  }
}
